use std::collections::HashSet;

use log::debug;

use program_structure::cfg::Cfg;
use program_structure::constants::Curve;
use program_structure::ir::{AssignOp, Expression, Meta, Statement};
use program_structure::report::{Report, ReportCollection};
use program_structure::report_code::ReportCode;
use program_structure::file_definition::{FileLocation, FileID};

const PROBLEMATIC_GOLDILOCK_TEMPLATES: [&str; 26] = [
    "BabyPbk",
    "AliasCheck",
    "CompConstant",
    "Num2Bits_strict",
    "Bits2Num_strict",
    "EdDSAVerifier",
    "EdDSAMiMCVerifier",
    "EdDSAMiMCSpongeVerifier",
    "EdDSAPoseidonVerifier",
    "EscalarMulAny",
    "MiMC7",
    "MultiMiMC7",
    "MiMCFeistel",
    "MiMCSponge",
    "Pedersen",
    "Bits2Point_Strict",
    "Point2Bits_Strict",
    "PoseidonEx",
    "Poseidon",
    "Sign",
    "SMTHash1",
    "SMTHash2",
    "SMTProcessor",
    "SMTProcessorLevel",
    "SMTVerifier",
    "SMTVerifierLevel",
];

const PROBLEMATIC_BLS12_381_TEMPLATES: [&str; 13] = [
    "AliasCheck",
    "CompConstant",
    "Num2Bits_strict",
    "Bits2Num_strict",
    "EdDSAVerifier",
    "EdDSAMiMCVerifier",
    "EdDSAMiMCSpongeVerifier",
