#[test]
fn test_cfg_from_if() {
    let src = r#"
        function f(x) {
            var y = 0;
            if (x > 0) {
                y = x;
                y += y * x;
            }
            return y + x;
        }
    "#;
    validate_cfg(
        src,
        &["x", "y"],
        &[3, 2, 1],
        &[0, 0, 0],
        &[(vec![], vec![1, 2]), (vec![0], vec![2]), (vec![0, 1], vec![])],
    );
}

#[test]
fn test_cfg_from_if_then_else() {
    let src = r#"
        function f(x) {
            var y = 0;
            if (x > 0) {
                y = x;
                y += y * x;
            } else {
                x = y;
                x += x + 1;
            }
            return y + x;
        }
    "#;
    validate_cfg(
        src,
        &["x", "y"],
        &[3, 2, 2, 1],
        &[0, 0, 0, 0],
        &[(vec![], vec![1, 2]), (vec![0], vec![3]), (vec![0], vec![3]), (vec![1, 2], vec![])],
    );
}

#[test]
fn test_cfg_from_while() {
    let src = r#"
        function f(x) {
            var y = 0;
            while (y < x) {
                y += y ** 2 + 1;
            }
            return y + x;
        }
    "#;
    validate_cfg(
        src,
        &["x", "y"],
        &[2, 1, 1, 1],
        &[0, 0, 1, 0],
        &[
            (vec![], vec![1]),
            // 0:
            // var y;
            // y = 0;
            (vec![0, 2], vec![2, 3]),
            // 1:
            // if (y < 0)
            (vec![1], vec![1]),
            //   2:
            //   y += y ** 2 + 1
            (vec![1], vec![]),
            // 3:
            // return y + x;
        ],
    );
}

