#[test]
fn test_cfg_with_non_unique_variables() {
    let src = r#"
        template T(n){
            signal input in;
            signal output out[2];

            component comp[2];
            if ((n % 2) == 0) {
                for(var i = 0; i < 2; i++) {
                    comp[i].in <== in;
                }
