                for(var i = 0; i < 2; i++) {
                    out[i] <== comp[i].out;
                }
            }
        }
    "#;

    validate_cfg(
        src,
        &["n", "in", "out", "comp", "i", "i.0"],
        &[4, 2, 1, 2, 2, 1, 2],
        &[0, 0, 0, 1, 0, 0, 1],
        &[
            (vec![], vec![1, 4]),
